var api_key;
if (
  location.pathname === "/chrome/welcome" ||
  location.pathname === "/firefox/welcome" ||
  location.pathname === "/settings"
) {
  api_key = document.getElementById("api_key").innerHTML.trim();
  Account.setApiKey(api_key);
}

$("#extension-installed").val(true);
$("#extension-heading").text("Chrome extension installed");
$("#download-extension").hide();

chrome.storage.sync.get("api_key", function(value) {
  if (value["api_key"] === "null") {
    $("#signup-extension").show();
    $("#extension-description").text(
      "This chrome extension works best with a TLDR This account. Sign up for an account now to get access to exclusive features."
    );
  } else {
    $("#signup-extension").hide();
    $("#extension-description").text(
      "Thank you for installing the TLDR This chrome extension. Please refer to the instructions below on how to use it."
    );
  }
});

window.display_keywords = false;
chrome.storage.sync.set({
  display_keywords: false
});
